from azure.ai.translation.text import TextTranslationClient, TranslatorCredential
from azure.ai.translation.text.models import InputTextItem

def ocr_translate(text: str, target_language: str, config=None):
    config = config or {}
    # Endpoint for Azure Translator should be like "https://api.cognitive.microsofttranslator.com/"
    # A sample key can be found in your Azure Translator resource.
    client = TextTranslationClient(
        endpoint=config['translator_endpoint'],
        credential=TranslatorCredential(config['translator_api_key'], config['translator_region'])
    )

    result = client.translate(content=[InputTextItem(text=text)], to=[target_language])
    if result and result[0].translations:
        return {'translated_text': result[0].translations[0].text}
    return {'translated_text': text}

from azure.ai.contentsafety import ContentSafetyClient
from azure.core.credentials import AzureKeyCredential
from azure.ai.contentsafety.models import AnalyzeTextOptions, TextCategory

def ocr_safety(text: str, config=None):
    config = config or {}
    # Endpoint for Azure Content Safety should be like "https://<your-resource-name>.cognitiveservices.azure.com/"
    client = ContentSafetyClient(
        endpoint=config['content_safety_endpoint'],
        credential=AzureKeyCredential(config['content_safety_api_key'])
    )

    request = AnalyzeTextOptions(
        text=text,
        categories=[TextCategory.HATE, TextCategory.SELF_HARM, TextCategory.SEXUAL, TextCategory.VIOLENCE]
    )

    response = client.analyze_text(request)

    safety_results = {}
    for category in response.categories_analysis:
        safety_results[category.category.value] = {
            'severity': category.severity,
            'detected': category.severity > 0 # Assuming severity > 0 means detected
        }
    return {'safety_results': safety_results}

from openai import AzureOpenAI

def ocr_embedding(text: str, config=None):
    config = config or {}
    # Endpoint for Azure OpenAI should be like "https://<your-resource-name>.openai.azure.com/"
    client = AzureOpenAI(
        azure_endpoint=config['azure_openai_endpoint'],
        api_key=config['azure_openai_api_key'],
        api_version=config.get('azure_openai_api_version', '2023-05-15') # Or other supported API version
    )

    # Model deployment name for embeddings, e.g., "text-embedding-ada-002"
    response = client.embeddings.create(input=text, model=config['azure_openai_embedding_deployment_name'])
    return {'embedding': response.data[0].embedding}
